primaryQuery:
run: order_items -> {
  where: year(created_at) = 2022
  aggregate: total_sales is sale_price.sum()
}

verifyQuery:
run: order_items -> {
  where: created_at >= @2022-01-01 and created_at < @2023-01-01
  group_by: mo is created_at.month
  aggregate: s is sale_price.sum()
} -> {
  aggregate: total_sales is s.sum()
}
